begin;
select plan(21);
insert into auth.users(id,is_anonymous) values('f5000000-0000-4000-8000-000000000001',true),('f5000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f5000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select public.create_code_band('Options','Leader','기타','1234','112233');
select set_config('opt.band',public.current_band_identity()->>'band_id',true);
select set_config('opt.me',public.current_band_identity()->'member'->>'id',true);
select set_config('opt.code',public.band_login_settings()->>'code',true);
-- Since 023 only members who saved a date attend it: the leader opts in to the plan days used below.
select public.save_band_availability((select jsonb_agg(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+n)::text)) from generate_series(1,5) n));
select is(public.band_login_settings()->>'skill_enabled','false','skill feature off by default');
select is(public.band_home_context()->>'skill_enabled','false','home flag off');
select is(public.current_band_identity()->'band'->>'skill_enabled','false','identity carries flag without another lookup');
select set_config('opt.song',public.add_song(current_setting('opt.band')::uuid,'Candidate','Artist')::text,true);
select public.vote_band_song(current_setting('opt.song')::bigint,'yes',null);

select set_config('opt.plan',public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('opt.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false,'  홍대 합주실  ')::text,true);
select is((select location from public.confirmed_plans where id=current_setting('opt.plan')::uuid),'홍대 합주실','location trimmed and missing skill/difficulty do not block when off');
select is(public.set_member_skill_enabled(true)->>'ok','true','leader can enable skill');
select is(public.band_planning_context()->>'skill_enabled','true','planning context updated');
select throws_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('opt.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false,'Place')$$,'P0001','SONG_NOT_ELIGIBLE','enabled feature restores missing-skill requirement');
select public.update_member_skill(current_setting('opt.me')::uuid,3::smallint);
select throws_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('opt.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false,'Place')$$,'P0001','SONG_NOT_ELIGIBLE','enabled feature requires difficulty even with assigned skills');
select public.update_song_difficulty(current_setting('opt.song')::bigint,'기타',4::smallint,0);
select lives_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('opt.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false,'Place')$$,'enabled feature accepts fully rated voted candidate');
select is(public.set_member_skill_enabled(false)->>'ok','true','leader can disable skill');
select is((public.band_planning_context()->'songs'->0->'difficulties'->>'기타')::int,4,'disable preserves stored difficulty');
select set_config('opt.unvoted',public.add_song(current_setting('opt.band')::uuid,'Unvoted candidate','Artist')::text,true);
select throws_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('opt.unvoted')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false,'Place')$$,'P0001','SONG_NOT_ELIGIBLE','disabled feature still requires votes');
select is((select skill from public.band_members where id=current_setting('opt.me')::uuid),3::smallint,'disable preserves stored skill');
select lives_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+3,array[current_setting('opt.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('opt.plan')::uuid,1,false)$$,'old seven-argument client can still edit');
select is((select location from public.confirmed_plans where id=current_setting('opt.plan')::uuid),'홍대 합주실','legacy client edit preserves location');
select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+4,'{}',(public.band_planning_context()->>'version')::bigint,current_setting('opt.plan')::uuid,2,false,'   ');
select is((select location from public.confirmed_plans where id=current_setting('opt.plan')::uuid),null::text,'location can be cleared');
select throws_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+5,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false,repeat('x',201))$$,'P0001','INVALID_INPUT','overlong venue rejected');
select set_config('request.jwt.claim.sub','f5000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('opt.code'),'1234');select public.register_band_profile('Member','베이스','246810');
select is(public.set_member_skill_enabled(true)->>'error','FORBIDDEN','ordinary member cannot enable feature');
select throws_ok($$select public.save_rehearsal_plan(current_setting('opt.band')::uuid,(now() at time zone 'Asia/Seoul')::date+5,'{}',(public.band_planning_context()->>'version')::bigint,current_setting('opt.plan')::uuid,3,false,'Other place')$$,'P0001','FORBIDDEN','member cannot change venue');
select ok(not has_function_privilege('anon','public.set_member_skill_enabled(boolean)','execute'),'anon cannot toggle');
select ok(not has_function_privilege('anon','public.save_rehearsal_plan(uuid,date,bigint[],bigint,uuid,integer,boolean,text)','execute'),'anon cannot set location');
select * from finish();rollback;
